import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const session: ChatSession = {
  sessionId: 'usage-session',
  userId: 'usage-user',
  entries: [{role: 'user', content: 'Use the tools.', timestamp: '2026-01-01T00:00:00.000Z'}],
};

const toolCall: MessageChunk = {type: 'tool_use', toolCall: {id: 'lookup-1', name: 'lookup', input: {}}};

function provider(rounds: MessageChunk[][]): AIProvider {
  let round = 0;

  return {
    async *sendMessage() {
      yield* rounds[round++] ?? [];
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

function stop(usage: UsageMetadata): MessageChunk {
  return {type: 'stop', stopReason: 'tool_use', usage};
}

describe('afterModelResponse total usage', () => {
  it('sums every provider call in a turn with two tool rounds', async () => {
    let reported: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, totalUsage) => {
        reported = totalUsage;
      },
    };
    const tools = new ToolRegistry();
    tools.register({name: 'lookup', description: 'Looks up a value.', inputSchema: {type: 'object'}}, async () => 'found');
    const orchestrator = createChatOrchestrator(
      provider([
        [toolCall, stop({inputTokens: 11, outputTokens: 2, totalTokens: 13})],
        [toolCall, stop({inputTokens: 23, outputTokens: 3, totalTokens: 26})],
        [{type: 'text', text: 'Done.'}, {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 37, outputTokens: 5, totalTokens: 42}}],
      ]),
      new PromptBuilder({identity: 'Usage test.'}),
      tools,
      {hooks}
    );

    await orchestrator.processMessage(session);

    expect(reported).toEqual({inputTokens: 71, outputTokens: 10, totalTokens: 81});
  });
});
EOF
timeout 300 npm test -- --runInBand src/orchestration/chatOrchestratorUsage.test.ts"
